<?php
include __DIR__ . '/../components/connect.php';
header('Content-Type: application/json; charset=utf-8');
$raw=file_get_contents('php://input')?:''; $payload=json_decode($raw,true); if(!is_array($payload))$payload=$_POST;
$secret=trim((string)(getenv('EASYPAISA_WEBHOOK_SECRET')?:'')); $required=(getenv('EASYPAISA_REQUIRE_WEBHOOK_SIGNATURE')?:'1')!=='0';
$given=(string)($_SERVER['HTTP_X_EASYPAISA_SIGNATURE']??$_SERVER['HTTP_X_SIGNATURE']??($payload['signature']??$payload['sign']??'')); $signature_ok=false;
if($secret!==''){$expected=hash_hmac('sha256',$raw,$secret);$signature_ok=$given!==''&&hash_equals($expected,$given);} elseif(!$required)$signature_ok=true;
$ref=trim((string)($payload['orderRefNumber']??$payload['merchant_order_ref']??$payload['merchantOrderNo']??$payload['order_id']??'')); $transaction_id=trim((string)($payload['transactionId']??$payload['transaction_id']??$payload['orderNo']??$payload['auth_token']??'')); $amount=(float)($payload['amount']??$payload['totalAmount']??0); $currency=strtoupper((string)($payload['currency']??'PKR')); $incoming=strtolower((string)($payload['status']??$payload['orderStatus']??'received')); $status=in_array($incoming,['success','completed','paid','000','2'],true)?'success':(in_array($incoming,['failed','cancelled','expired','declined','1','3'],true)?'failed':'pending');
if($ref===''||$amount<=0){http_response_code(400);echo json_encode(['ok'=>false,'error'=>'missing payment reference or amount']);exit;}
try{$order_id=ctype_digit($ref)?(int)$ref:null; $stmt=$conn->prepare("INSERT INTO payment_transactions(provider,order_id,merchant_order_ref,provider_transaction_id,amount,currency,status,signature_valid,raw_payload) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE provider_transaction_id=VALUES(provider_transaction_id), status=VALUES(status), signature_valid=VALUES(signature_valid), raw_payload=VALUES(raw_payload)"); $stmt->execute(['easypaisa',$order_id,$ref,$transaction_id,$amount,$currency,$status,$signature_ok?1:0,$raw?:json_encode($payload)]); if($signature_ok&&$status==='success'&&$order_id){$up=$conn->prepare("UPDATE orders SET payment_status='completed' WHERE id=? AND CAST(total_price AS DECIMAL(12,2))=?");$up->execute([$order_id,$amount]);} if(!$signature_ok){http_response_code(401);echo json_encode(['ok'=>false,'error'=>'signature verification failed']);exit;} echo json_encode(['ok'=>true,'status'=>$status]);}catch(Throwable $e){error_log('Easypaisa webhook error: '.$e->getMessage());http_response_code(500);echo json_encode(['ok'=>false,'error'=>'webhook processing failed']);}
